package cn.zhuatech.hragent.controller; import cn.zhuatech.hragent.common.ApiResponse; import cn.zhuatech.hragent.dto.HrAgentDto.*; import cn.zhuatech.hragent.service.HrAgentService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final HrAgentService service;public OperationsAdminController(HrAgentService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
